/**
 * Detects the media type of the resource at the given URL. The type
 * detection is based on the document content and a potential known
 * file extension included in the URL.
 * <p>
 * Use the {@link #detect(String)} method when you want to detect the
 * type of the document without actually accessing the URL.
 *
 * @param url
 * 		the URL of the resource
 * @return detected media type
 * @throws IOException
 * 		if the resource can not be read
 */
public String detect(URL url) throws IOException {
    Metadata metadata = new Metadata();
    try (InputStream stream = TikaInputStream.get(url, metadata)) {
        // PATH: Test should invoke the next Tika.detect(...) [step in execution path]
        return detect(stream, metadata);
    }
}

public MediaType detect(TikaInputStream tis, Metadata metadata, ParseContext parseContext) throws IOException {
    List<MimeType> possibleTypes = new ArrayList<>();
    // Get type based on magic prefix
    if (tis != null) {
        tis.mark(mimeTypes.getMinLength());
        try {
            byte[] prefix = mimeTypes.readMagicHeader(tis);
            // defensive copy
            // PATH: Test should invoke the next MimeTypes.getMimeType(...) [step in execution path]
            possibleTypes.addAll(mimeTypes.getMimeType(prefix));
        } finally {
            tis.reset();
        }
    }
    MimeType extHint = null;
    // Get type based on resourceName hint (if available)
    String resourceName = metadata.get(TikaCoreProperties.RESOURCE_NAME_KEY);
    if (resourceName != null) {
        String name = null;
        // Deal with a URI or a path name in as the resource name
        try {
            URI uri = new URI(resourceName);
            String path = uri.getPath();
            if (path != null) {
                int slash = path.lastIndexOf('/');
                if ((slash + 1) < path.length()) {
                    name = path.substring(slash + 1);
                }
            }
        } catch (URISyntaxException e) {
            name = resourceName;
        }
        if (name != null) {
            // MimeType hint = getMimeType(name);
            extHint = mimeTypes.getMimeType(name);
            // If we have some types based on mime magic, try to specialise
            // and/or select the type based on that
            // Otherwise, use the type identified from the name
            // possibleTypes = applyHint(possibleTypes, hint);
        }
    }
    // Get type based on metadata hint (if available)
    MimeType metaHint = null;
    String typeName = metadata.get(Metadata.CONTENT_TYPE);
    if (typeName != null) {
        try {
            // MimeType hint = forName(typeName);
            metaHint = mimeTypes.forName(typeName);
            // possibleTypes = applyHint(possibleTypes, hint);
        } catch (MimeTypeException e) {
            // Malformed type name, ignore
        }
    }
    /* the following calls the probability selection. */
    return applyProbilities(possibleTypes, extHint, metaHint);
}

/**
 * Returns the MIME type that best matches the given first few bytes
 * of a document stream. Returns application/octet-stream if no better
 * match is found.
 * <p>
 * If multiple matches are found, the best (highest priority) matching
 * type is returned. If multiple matches are found with the same priority,
 * then all of these are returned.
 * <p>
 * The given byte array is expected to be at least {@link #getMinLength()}
 * long, or shorter only if the document stream itself is shorter.
 *
 * @param data
 * 		first few bytes of a document stream
 * @return matching MIME type
 */
List<MimeType> getMimeType(byte[] data) {
    if (data == null) {
        throw new IllegalArgumentException("Data is missing");
    } else if (data.length == 0) {
        // See https://issues.apache.org/jira/browse/TIKA-483
        return rootMimeTypeL;
    }
    // Then, check for magic bytes
    List<MimeType> result = new ArrayList<>(1);
    int currentPriority = -1;
    for (Magic magic : magics) {
        if ((currentPriority > 0) && (currentPriority > magic.getPriority())) {
            break;
        }
        if (magic.eval(data)) {
            result.add(magic.getType());
            currentPriority = magic.getPriority();
        }
    }
    if (!result.isEmpty()) {
        for (int i = 0; i < result.size(); i++) {
            final MimeType matched = result.get(i);
            // When detecting generic XML (or possibly XHTML),
            // extract the root element and match it against known types
            if ("application/xml".equals(matched.getName()) || "text/html".equals(matched.getName())) {
                XmlRootExtractor extractor = new XmlRootExtractor();
                // PATH: Test should invoke the next XmlRootExtractor.extractRootElement(...) [step in execution path]
                QName rootElement = extractor.extractRootElement(data);
                if (rootElement != null) {
                    for (MimeType type : xmls) {
                        if (type.matchesXML(rootElement.getNamespaceURI(), rootElement.getLocalPart())) {
                            result.set(i, type);
                            break;
                        }
                    }
                } else if ("application/xml".equals(matched.getName())) {
                    // Our XML magic is higher than our HTML magic
                    // So, if we got here, we might have a HTML file that's
                    // invalid XML. So, try our HTML magics explicitly (TIKA-2419)
                    boolean isHTML = false;
                    for (Magic magic : magics) {
                        if (!magic.getType().equals(htmlMimeType)) {
                            continue;
                        }
                        if (magic.eval(data)) {
                            isHTML = true;
                            break;
                        }
                    }
                    // Otherwise, downgrade from application/xml to text/plain
                    // since the document seems not to be well-formed.
                    if (isHTML) {
                        result.set(i, htmlMimeType);
                    } else {
                        result.set(i, textMimeType);
                    }
                }
            }
        }
        return result;
    }
    // Finally, assume plain text if no control bytes are found
    try {
        TextDetector detector = new TextDetector(getMinLength());
        try (TikaInputStream tis = TikaInputStream.get(data)) {
            MimeType type = forName(detector.detect(tis, new Metadata(), new ParseContext()).toString());
            return Collections.singletonList(type);
        }
    } catch (Exception e) {
        return rootMimeTypeL;
    }
}

public QName extractRootElement(byte[] data) {
    // this loop should be very rare
    while (true) {
        try {
            // PATH: Test should invoke the next XmlRootExtractor.extractRootElement(...) [step in execution path]
            return extractRootElement(new UnsynchronizedByteArrayInputStream(data), true);
        } catch (MalformedCharException e) {
            // see TIKA-3596, try to handle truncated/bad encoded XML files
            int newLen = data.length / 2;
            if ((newLen % 2) == 1) {
                newLen--;
            }
            if (newLen > 0) {
                data = Arrays.copyOf(data, newLen);
            } else {
                break;
            }
        }
    } 
    return null;
}

private QName extractRootElement(InputStream stream, boolean throwMalformed) {
    ExtractorHandler handler = new ExtractorHandler();
    try {
        // PATH: Test should invoke the next CloseShieldInputStream.wrap(...) [step in execution path]
        XMLReaderUtils.parseSAX(CloseShieldInputStream.wrap(stream), handler, EMPTY_CONTEXT);
    } catch (SecurityException e) {
        throw e;
    } catch (Exception e) {
        if (throwMalformed && ((e instanceof CharConversionException) || (e.getCause() instanceof CharConversionException))) {
            throw new MalformedCharException(e);
        }
    }
    return handler.rootElement;
}

